#include <iostream>
#include <string>
#include <utility>

class Instrument {
public:
    explicit Instrument(std::string symbol) : symbol_{std::move(symbol)} {}
    const std::string& symbol() const { return symbol_; }
protected:
    double tickSize_ = 0.01;    // derived classes may use this
private:
    std::string symbol_;        // nobody outside Instrument may name this
};

class Future : public Instrument {
public:
    Future(std::string symbol, double tickSize, double multiplier)
        : Instrument{std::move(symbol)}, tickSize_{tickSize}, multiplier_{multiplier} {}
    double tickValue() const { return tickSize_ * multiplier_; }  // own member
    double baseTick() const { return tickSize_; }                 // OK: protected
    // double s = symbol_;   // would NOT compile: symbol_ is private in the base
private:
    double tickSize_, multiplier_;
};

int main() {
    Future f{"ESZ5", 0.25, 50.0};
    std::cout << f.symbol() << " tick value " << f.tickValue() << '\n';
}

