guidedExercise.solution:
buyingPower() is $10000 + 40000 = 50000$; balance() is 10000. `m.balance_` is protected, and non-member code (main) may only touch public members - that is the access ladder doing its job.

```cpp
#include <iostream>

class Account {
public:
    explicit Account(double cash) : balance_{cash} {}
    void deposit(double amt) { if (amt > 0.0) balance_ += amt; }
    void withdraw(double amt) { if (amt > 0.0 && amt <= balance_) balance_ -= amt; }
    double balance() const { return balance_; }
protected:
    double balance_;   // subclasses may use; outsiders may not
};

class MarginAccount : public Account {
public:
    explicit MarginAccount(double cash, double limit)
        : Account{cash}, limit_{limit} {}          // base subobject first
    double buyingPower() const { return balance_ + limit_; }
private:
    double limit_;
};

int main() {
    MarginAccount m{10000.0, 40000.0};
    std::cout << m.buyingPower() << '\n';   // 50000
    std::cout << m.balance() << '\n';       // 10000
    // m.balance_ = 1e9;   // compile error: protected, and main is not a member
}
```

independentExercise.solution:
Intrinsic at spot 155 with strike 150 is $\max(155 - 150, 0) = 5$.

```cpp
#include <algorithm>
#include <iostream>
#include <string>
#include <utility>

class Instrument {
public:
    explicit Instrument(std::string symbol) : symbol_{std::move(symbol)} {}
    const std::string& symbol() const { return symbol_; }
protected:
    double tickSize_ = 0.01;
private:
    std::string symbol_;
};

class Bond : public Instrument {
public:
    Bond(std::string symbol, double coupon)
        : Instrument{std::move(symbol)}, coupon_{coupon} {}
    double coupon() const { return coupon_; }
private:
    double coupon_;
};

class EquityOption : public Instrument {
public:
    EquityOption(std::string symbol, double strike)
        : Instrument{std::move(symbol)}, strike_{strike} {}
    double intrinsic(double spot) const { return std::max(spot - strike_, 0.0); }
private:
    double strike_;
};

int main() {
    Bond b{"UST10Y", 0.0425};
    EquityOption o{"AAPL 260115C150", 150.0};
    std::cout << b.symbol() << " coupon " << b.coupon() << '\n';
    std::cout << o.symbol() << " intrinsic at 155: " << o.intrinsic(155.0) << '\n';
}
```

